{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Lapatinib, a close structural analogue sharing the anilino-heteroaryl and lipophilic aryl ether features, showed very low CNS distribution in rats (brain/plasma <0.13), indicating poor meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Lapatinib's low brain concentrations are explained by P-gp/ABCG2 efflux at the BBB; the query's similar lipophilic, high-MW aniline-heteroaryl scaffold is likely to be recognized by the same transporters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Erlotinib, another close analogue with a neutral, lipophilic quinazoline aniline, has a very low unbound brain-to-plasma ratio (<0.2) due to efflux/diffusion limitation, supporting poor CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The structurally related quinazoline HDAC inhibitor CUDC-101 showed poor brain accumulation on PET, consistent with inefficient BBB crossing in this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "OSI-420, an erlotinib metabolite with similar neutral polar side chains, achieved only 2.3% CSF/plasma AUC in primates, indicating limited CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "AZD3759, a designed CNS-penetrant EGFR TKI, achieved ~1:1 CSF/plasma in humans, showing that related scaffolds can achieve meaningful CNS access when optimized with CNS-design features; however, the query lacks these features.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Compound 1a, a close quinazoline analogue with a morpholinomethyl group, showed good rat brain penetration (Kpuu,brain 0.47), but this is attributable to the basic morpholine moiety absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, lipophilic, neutral anilino-pyrazolopyrimidine BTK inhibitor. The most transferable experimental evidence from close analogues (lapatinib, erlotinib, CUDC-101, OSI-420) shows poor brain/CSF penetration and efflux liability. The few positive CNS-penetrant analogues achieve their brain exposure through basic amine/CNS-design features absent in the query. Physicochemical prior also predicts low passive BBB permeability. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain, CSF, or PET data for the query molecule itself.",
    "Transfer relies on analogues with modest Morgan similarity (0.24-0.30).",
    "No direct evidence on whether the query is a substrate for P-gp/ABCG2 or an active uptake transporter.",
    "Species differences in BBB transporter expression and CSF sampling methods limit quantitative extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

